def tok_desc(t):
    if t.t=='EOF': return 'end of file'
    if t.t=='VAR': return f'token "${t.v}"'
    if t.t=='STRING': return 'string'
    if t.t=='DSTRING': return 'string'
    if t.t=='NUM': return f'token "{t.v}"'
    if t.t=='INLINE': return 'inline HTML'
    return f'token "{t.v}"'

