        return t
    def accept_op(self,op):
        t=self.peek()
        if t.t=='OP' and t.v==op: self.next(); return True
        return False
    def expect_op(self,op):
        t=self.peek()
        if not (t.t=='OP' and t.v==op): self.err_expect(op)
        return self.next()
    def accept_ident(self,name):
        t=self.peek()
        if t.t=='IDENT' and t.v.lower()==name: self.next(); return True
        return False
    def expect_ident(self,name=None):
        t=self.peek()
        if t.t!='IDENT': self.err_expect(name or 'identifier')
        if name and t.v.lower()!=name: self.err_expect(name)
        return self.next()
    def is_op(self,op):
        t=self.peek(); return t.t=='OP' and t.v==op
    def is_ident(self,name):
        t=self.peek(); return t.t=='IDENT' and t.v.lower()==name
    def err(self,msg, tok=None):
        tok=tok or self.peek()
        raise ParseExc(msg,tok.line,self.file)
    def err_expect(self,what):
        t=self.peek()
        desc=tok_desc(t)
        raise ParseExc(f"syntax error, unexpected {desc}, expecting {what}",t.line,self.file)
    # Program
    def parse_program(self):
        stmts=[]
        while True:
            t=self.peek()
            if t.t=='EOF': break
            if t.t=='INLINE':
                self.next(); stmts.append(('inline',t.line,t.v)); continue
            if t.t=='OPEN': self.next(); continue
            if t.t=='OPEN_ECHO':
                self.next(); e=self.parse_expr(); stmts.append(('echo',t.line,[e]))
                # optional ;
                self.accept_op(';')
                continue
            if t.t=='CLOSE': self.next(); continue
            s=self.parse_statement()
            if s is not None:
                if isinstance(s,list): stmts.extend(s)
                else: stmts.append(s)
        return stmts
    def parse_block_stmts(self):
        # assumes { consumed or single? returns list until }
        stmts=[]
        while not self.is_op('}') and self.peek().t not in ('EOF',):
            t=self.peek()
            if t.t=='INLINE': self.next(); stmts.append(('inline',t.line,t.v)); continue
            if t.t in ('OPEN','CLOSE','OPEN_ECHO'):
                if t.t=='OPEN_ECHO':
                    self.next(); e=self.parse_expr(); stmts.append(('echo',t.line,[e])); self.accept_op(';')
                else: self.next()
                continue
            s=self.parse_statement()
            if s is not None:
                if isinstance(s,list): stmts.extend(s)
                else: stmts.append(s)
        return stmts
    def parse_body(self):
        # either { ... } or single statement or : ... endif style handled by caller?
        if self.is_op('{'):
            self.next(); stmts=self.parse_block_stmts(); self.expect_op('}'); return stmts
        else:
            s=self.parse_statement()
            if s is None: return []
            return s if isinstance(s,list) else [s]
    def parse_statement(self):
        t=self.peek()
        line=t.line
        if t.t=='OP' and t.v==';': self.next(); return None
        if t.t=='OP' and t.v=='{': self.next(); b=self.parse_block_stmts(); self.expect_op('}'); return ('block',line,b)
        if t.t=='IDENT':
            kw=t.v.lower()
            if kw=='if': return self.parse_if()
            if kw=='while': return self.parse_while()
            if kw=='do': return self.parse_do()
            if kw=='for': return self.parse_for()
            if kw=='foreach': return self.parse_foreach()
            if kw=='switch': return self.parse_switch()
            if kw=='try': return self.parse_try()
            if kw=='function': return self.parse_function_decl()
            if kw in ('class','interface','trait','enum'): return self.parse_class_decl()
            if kw=='abstract' or kw=='final' or kw=='readonly':
                # lookahead class
                save=self.pos; self.next()
                if self.is_ident('class') or self.is_ident('interface') or self.is_ident('trait') or self.is_ident('enum'):
                    self.pos=save; return self.parse_class_decl()
                self.pos=save
            if kw=='return':
                self.next()
                if self.is_op(';'): self.next(); return ('return',line,None)
                if self.peek().t in ('CLOSE','EOF') or self.is_op('}'): return ('return',line,None)
                e=self.parse_expr(); self.accept_op(';'); return ('return',line,e)
            if kw=='break' or kw=='continue':
                self.next(); num=None
                if not self.is_op(';') and self.peek().t not in ('CLOSE',):
                    num=self.parse_expr()
                self.accept_op(';'); return (kw,line,num)
            if kw=='echo':
                self.next(); exprs=[]
                exprs.append(self.parse_expr())
                while self.accept_op(','): exprs.append(self.parse_expr())
                self.accept_op(';'); return ('echo',line,exprs)
            if kw=='global':
                self.next(); vars=[]
                while True:
                    vt=self.next()
                    if vt.t!='VAR': self.err("syntax error, unexpected token",vt)
                    vars.append(vt.v)
                    if not self.accept_op(','): break
                self.accept_op(';'); return ('global',line,vars)
            if kw=='static':
                # static var decl or static function/class etc handled in expr? Check if VAR following or function
                nxt=self.peek(1)
                if nxt.t=='VAR':
                    self.next(); decls=[]
                    while True:
                        vt=self.next(); name=vt.v; init=None
                        if self.accept_op('='): init=self.parse_expr()
                        decls.append((name,init))
                        if not self.accept_op(','): break
                    self.accept_op(';'); return ('staticvar',line,decls)
                # else fallthrough to expr (static method call etc)
            if kw=='unset':
                self.next(); self.expect_op('('); exprs=[]
                if not self.is_op(')'):
                    exprs.append(self.parse_expr())
                    while self.accept_op(','): exprs.append(self.parse_expr())
                self.expect_op(')'); self.accept_op(';'); return ('unset',line,exprs)
            if kw=='const':
                self.next(); decls=[]
                while True:
                    nt=self.next(); name=nt.v if nt.t=='IDENT' else self.err("const name",nt)
                    self.expect_op('='); e=self.parse_expr(); decls.append((name,e))
                    if not self.accept_op(','): break
                self.accept_op(';'); return ('constdecl',line,decls,self.ns)
            if kw=='namespace':
                self.next()
                if self.is_op('{'):
                    self.next(); old=self.ns; self.ns=""; b=self.parse_block_stmts(); self.expect_op('}'); self.ns=old; return ('block',line,b)
                if self.is_op(';'): self.next(); self.ns=""; return None
                name=self.parse_name_str()
                if self.is_op('{'):
                    self.next(); old=self.ns; self.ns=name; b=self.parse_block_stmts(); self.expect_op('}'); self.ns=old; return ('namespaceblock',line,name,b)
                self.accept_op(';'); self.ns=name; return ('namespace',line,name)
            if kw=='use':
                # could be use in closure handled in expr; at statement level trait use inside class handled elsewhere; here import
                # peek: function/const or name
                self.next()
                # closure use is not statement
                is_func=self.accept_ident('function'); is_const=self.accept_ident('const')
                items=[]
                while True:
                    nm=self.parse_name_str()
                    alias=nm.split('\\')[-1]
                    if self.accept_ident('as'):
                        at=self.next(); alias=at.v
                    items.append((nm,alias))
                    if not self.accept_op(','): break
                self.accept_op(';')
                for nm,alias in items: self.uses[alias.lower()]=(nm,is_func,is_const)
                return ('use',line,items)
            if kw=='declare':
                self.next(); 
                if self.is_op('('):
                    self.next()
                    while not self.is_op(')') and self.peek().t!='EOF':
                        self.next()
                    self.expect_op(')')
                    if self.is_op('{'): return ('block',line,self.parse_body())
                    elif self.is_op(';'): self.next(); return None
                    else: return ('block',line,self.parse_body())
                self.accept_op(';'); return None
            if kw=='goto':
                self.next(); lt=self.next(); self.accept_op(';'); return ('goto',line,lt.v)
            if kw=='yield' or True:
                pass
        # label?
        if t.t=='IDENT' and self.peek(1).t=='OP' and self.peek(1).v==':':
            name=t.v; self.next(); self.next(); return ('label',line,name)
        # expression statement
        e=self.parse_expr()
        self.accept_op(';')
        return ('expr',line,e)
    def parse_if(self):
        line=self.peek().line; self.expect_ident('if'); self.expect_op('('); cond=self.parse_expr(); self.expect_op(')')
        if self.is_op(':'):
            self.next(); body=[]
            while not self.is_ident('elseif') and not self.is_ident('else') and not self.is_ident('endif'):
                body.append(self.parse_statement())
            body=[s for s in body if s is not None]
            # flatten lists?
            branches=[(cond,body)]; else_body=None
            while self.is_ident('elseif'):
                self.next(); self.expect_op('('); c=self.parse_expr(); self.expect_op(')'); self.expect_op(':'); b=[]
                while not self.is_ident('elseif') and not self.is_ident('else') and not self.is_ident('endif'):
                    s=self.parse_statement(); 
                    if s is not None: b.append(s)
                branches.append((c,b))
            if self.is_ident('else'):
                self.next(); self.accept_op(':'); else_body=[]
                while not self.is_ident('endif'):
                    s=self.parse_statement()
                    if s is not None: else_body.append(s)
            self.expect_ident('endif'); self.accept_op(';')
            return ('ifalt',line,branches,else_body)
        body=self.parse_body()
        branches=[(cond,body)]; else_body=None
        while self.is_ident('elseif'):
            self.next(); self.expect_op('('); c=self.parse_expr(); self.expect_op(')'); b=self.parse_body(); branches.append((c,b))
        if self.is_ident('else'):
            self.next(); else_body=self.parse_body()
        return ('if',line,branches,else_body)
    def parse_while(self):
        line=self.peek().line; self.expect_ident('while'); self.expect_op('('); cond=self.parse_expr(); self.expect_op(')')
        if self.is_op(':'):
            self.next(); body=[]
            while not self.is_ident('endwhile'):
                s=self.parse_statement()
                if s is not None: body.append(s)
            self.expect_ident('endwhile'); self.accept_op(';'); return ('while',line,cond,body)
        return ('while',line,cond,self.parse_body())
    def parse_do(self):
        line=self.peek().line; self.expect_ident('do'); body=self.parse_body(); self.expect_ident('while'); self.expect_op('('); cond=self.parse_expr(); self.expect_op(')'); self.accept_op(';'); return ('do',line,body,cond)
    def parse_for(self):
        line=self.peek().line; self.expect_ident('for'); self.expect_op('(')
        init=[]
        if not self.is_op(';'):
            init.append(self.parse_expr())
            while self.accept_op(','): init.append(self.parse_expr())
        self.expect_op(';'); cond=[]
        if not self.is_op(';'):
            cond.append(self.parse_expr())
            while self.accept_op(','): cond.append(self.parse_expr())
        self.expect_op(';'); loop=[]
        if not self.is_op(')'):
            loop.append(self.parse_expr())
            while self.accept_op(','): loop.append(self.parse_expr())
        self.expect_op(')')
        if self.is_op(':'):
            self.next(); body=[]
            while not self.is_ident('endfor'):
                s=self.parse_statement()
                if s is not None: body.append(s)
            self.expect_ident('endfor'); self.accept_op(';'); return ('for',line,init,cond,loop,body)
        return ('for',line,init,cond,loop,self.parse_body())
    def parse_foreach(self):
        line=self.peek().line; self.expect_ident('foreach'); self.expect_op('('); expr=self.parse_expr()
        # expr may have parsed as ??? foreach syntax: expr as ...
        self.expect_ident('as')
        # key/value parsing: could be $k => $v, $v, &$v, list(...)
        first=self.parse_foreach_target()
        key=None; val=first
        if self.accept_op('=>'):
            key=first; val=self.parse_foreach_target()
        self.expect_op(')')
        if self.is_op(':'):
            self.next(); body=[]
            while not self.is_ident('endforeach'):
                s=self.parse_statement()
                if s is not None: body.append(s)
            self.expect_ident('endforeach'); self.accept_op(';'); return ('foreach',line,expr,key,val,body)
        return ('foreach',line,expr,key,val,self.parse_body())
    def parse_foreach_target(self):
        line=self.peek().line
        byref=False
        if self.accept_op('&'): byref=True
        if self.is_ident('list') or self.is_ident('array'):
            # list(...)
            is_list=self.is_ident('list'); self.next(); self.expect_op('('); items=[]
            while not self.is_op(')'):
                if self.is_op(','): self.next(); items.append(None); continue
                it=self.parse_foreach_target(); items.append(it)
                if not self.accept_op(','): break
            self.expect_op(')'); return ('listtarget',line,items,byref)
        e=self.parse_expr()
        return ('vartarget',line,e,byref)
    def parse_switch(self):
        line=self.peek().line; self.expect_ident('switch'); self.expect_op('('); expr=self.parse_expr(); self.expect_op(')')
        cases=[] # list of (value_expr or None, stmts)
        if self.is_op('{') or self.is_op(':'):
            brace=self.is_op('{')
            if brace: self.next()
            else: self.next()
            cur_stmts=None; cur_val='__pending__'
            while True:
                if brace and self.is_op('}'): self.next(); break
                if not brace and self.is_ident('endswitch'): self.next(); self.accept_op(';'); break
                if self.peek().t=='EOF': break
                if self.is_ident('case'):
                    self.next(); v=self.parse_expr(); self.accept_op(':'); self.accept_op(';')
                    cur_stmts=[]; cases.append((v,cur_stmts)); continue
                if self.is_ident('default'):
                    self.next(); self.accept_op(':'); self.accept_op(';'); cur_stmts=[]; cases.append((None,cur_stmts)); continue
                s=self.parse_statement()
                if cur_stmts is None:
                    cur_stmts=[]; cases.append(('__pre__',cur_stmts))
                if s is not None:
                    if isinstance(s,list): cur_stmts.extend(s)
                    else: cur_stmts.append(s)
            return ('switch',line,expr,cases)
        else:
            body=self.parse_body(); return ('switch',line,expr,[])
    def parse_try(self):
        line=self.peek().line; self.expect_ident('try'); body=self.parse_body(); catches=[]; fin=None
        while self.is_ident('catch'):
            self.next(); self.expect_op('(')
            types=[]
            while True:
                types.append(self.parse_name_str())
                if not self.accept_op('|'): break
            var=None
            if self.peek().t=='VAR': var=self.next().v
            self.expect_op(')'); cb=self.parse_body(); catches.append((types,var,cb))
        if self.is_ident('finally'):
            self.next(); fin=self.parse_body()
        return ('try',line,body,catches,fin)
    def parse_params(self):
        params=[]
        self.expect_op('(')
        while not self.is_op(')'):
            line=self.peek().line
            # attributes #[...]
            while self.is_op('#'):
                # will be handled? attribute tokens: # [ ... ] -> our lexer has # comment! Wait inside php # starts comment to end of line, but #[ is attribute. Our lexer treats # as comment! Need fix later.
                pass
            # type hints: consume type expression up to VAR or ... or &
            typ=None; byref=False; variadic=False
            # visibility for promoted properties
            vis=None
            while self.is_ident('public') or self.is_ident('private') or self.is_ident('protected') or self.is_ident('readonly'):
                vis=self.next().v.lower()
            # parse optional type: sequence of IDENT \ | & ? etc until VAR/.../&
            # Tentative: collect tokens while next is VAR is break; if token is '&' could be byref or intersection - ambiguous.
            # Look ahead for VAR
            save=self.pos
            type_toks=[]
            # handle ? type
            if self.is_op('?'): self.next(); type_toks.append('?')
            # consume name(s) with | & \
            while True:
                t=self.peek()
                if t.t=='IDENT' or (t.t=='OP' and t.v=='\\'):
                    type_toks.append(self.next().v); continue
                if t.t=='OP' and t.v in ('|',):
                    type_toks.append(self.next().v); continue
                if t.t=='OP' and t.v=='&':
                    # if next after & is VAR or IDENT? intersection type A&B $x ; byref &$x
                    # peek2
                    nxt=self.peek(1)
                    if nxt.t=='VAR' or (nxt.t=='OP' and nxt.v=='...'):
                        break
                    if nxt.t=='IDENT':
                        type_toks.append(self.next().v); continue
                    break
                break
            if self.peek().t=='OP' and self.peek().v=='&':
                self.next(); byref=True
            if self.is_op('...'):
                self.next(); variadic=True
            vt=self.peek()
            if vt.t!='VAR':
                # no var - error
                self.err(f"syntax error, unexpected {tok_desc(vt)}")
            var=self.next().v
            default=None; has_def=False
            if self.accept_op('='): default=self.parse_expr(); has_def=True
            params.append({'name':var,'default':default,'has_def':has_def,'byref':byref,'variadic':variadic,'type':type_toks,'vis':vis,'line':line})
            if not self.accept_op(','): break
            if self.is_op(')'): break
        self.expect_op(')')
        # return type : type (allow ? A|B etc, also : never etc) consume until { or ; or =>
        if self.accept_op(':'):
            while not self.is_op('{') and not self.is_op(';') and not self.is_op('=>') and self.peek().t!='EOF':
                # stop at? body starts
                self.next()
        return params
    def parse_function_decl(self):
        line=self.peek().line; self.expect_ident('function')
        byref=False
        if self.accept_op('&'): byref=True
        name=None
        if self.peek().t=='IDENT': name=self.next().v
        params=self.parse_params()
        # use (...) for closures? function decl statement shouldn't
        uses=[]
        if self.is_ident('use'):
            self.next(); self.expect_op('(')
            while not self.is_op(')'):
                b=False
                if self.accept_op('&'): b=True
                vt=self.next(); uses.append((vt.v,b))
                if not self.accept_op(','): break
            self.expect_op(')')
            if self.accept_op(':'):
                while not self.is_op('{') and not self.is_op(';'): self.next()
        if self.is_op(';'):
            self.next(); body=None
        else:
            body=self.parse_body()
        fq=name
        if name and self.ns and '\\' not in name: fq=self.ns+'\\'+name
        return ('funcdecl',line,name,params,body,uses,fq)
    def parse_name_str(self):
        parts=[]
        if self.is_op('\\'): self.next(); parts.append('')
        while True:
            t=self.peek()
            if t.t=='IDENT': parts.append(self.next().v)
            else: break
            if self.is_op('\\'): self.next(); continue
            break
        return '\\'.join([p for p in parts if p!='']) if parts and parts[0]!='' else ('\\'+'\\'.join(parts[1:]) if parts else '')
    def parse_class_decl(self):
        line=self.peek().line
        modifiers=[]
        while self.is_ident('abstract') or self.is_ident('final') or self.is_ident('readonly'):
            modifiers.append(self.next().v.lower())
        kind_tok=self.next(); kind=kind_tok.v.lower()
        name=None
        if kind=='enum':
            if self.peek().t=='IDENT': name=self.next().v
            # backed type : int/string
            if self.accept_op(':'):
                while self.peek().t=='IDENT': self.next()
        elif kind in ('class','interface','trait'):
            if self.peek().t=='IDENT' and not self.is_ident('extends') and not self.is_ident('implements'):
                name=self.next().v
        else:
            self.err("class expected",kind_tok)
        parent=None; interfaces=[]
        if self.accept_ident('extends'):
            parent=self.parse_name_str()
        if self.accept_ident('implements'):
            while True:
                interfaces.append(self.parse_name_str())
                if not self.accept_op(','): break
        # anonymous class args (
        if self.is_op('('):
            # skip args for anonymous
            self.pos+=0
            args=self.parse_call_args()
        self.expect_op('{')
        members=[]; 
        while not self.is_op('}'):
            if self.peek().t=='EOF': break
            m=self.parse_member(kind)
            if m is not None:
                if isinstance(m,list): members.extend(m)
                else: members.append(m)
        self.expect_op('}')
        fq=name
        if name and self.ns and '\\' not in name: fq=self.ns+'\\'+name
        return ('classdecl',line,kind,name,modifiers,parent,interfaces,members,fq)
    def parse_member(self,kind):
        line=self.peek().line
        if self.is_op(';'): self.next(); return None
        # enum case
        if self.is_ident('case'):
            self.next(); nt=self.next(); nm=nt.v; val=None
            if self.accept_op('='): val=self.parse_expr()
            self.accept_op(';'); return ('enumcase',line,nm,val)
        # trait use
        if self.is_ident('use'):
            # could be trait use: use A, B { ... } or use A;
            save=self.pos; self.next()
            traits=[]
            try:
                while True:
                    traits.append(self.parse_name_str())
                    if not self.accept_op(','): break
                if self.is_op('{'):
                    self.next()
                    # skip adaptations until }
                    depth=1
                    while depth>0 and self.peek().t!='EOF':
                        t=self.next()
                        if t.t=='OP' and t.v=='{': depth+=1
                        if t.t=='OP' and t.v=='}': depth-=1
                    self.accept_op(';'); return ('traituse',line,traits)
                self.accept_op(';'); return ('traituse',line,traits)
            except Exception:
                self.pos=save
                # fallthrough
        modifiers=[]
        while self.peek().t=='IDENT' and self.peek().v.lower() in ('public','private','protected','static','abstract','final','var','readonly'):
            modifiers.append(self.next().v.lower())
        if self.is_ident('const'):
            self.next(); decls=[]
            # optional type
            save=self.pos
            while self.peek().t=='IDENT' and self.peek(1).t=='OP' and self.peek(1).v=='=':
                break
            # skip type if next token ident and following is ident?
            # simple: if two idents, first is type
            if self.peek().t=='IDENT' and self.peek(1).t=='IDENT': self.next()
            if self.is_op('?'): 
                pass
            while True:
                nt=self.next(); nm=nt.v; self.expect_op('='); e=self.parse_expr(); decls.append((nm,e))
                if not self.accept_op(','): break
            self.accept_op(';'); return ('classconst',line,modifiers,decls)
        if self.is_ident('function'):
            fd=self.parse_function_decl()
            # fd: funcdecl line name params body uses fq
            return ('method',line,modifiers,fd[3],fd[4],fd[5])  # name? Wait parse_function_decl returns ...
            # Actually need name; handled below unreachable
        if self.peek().t=='VAR':
            props=[]
            while True:
                vt=self.next(); nm=vt.v; init=None; has=False
                if self.accept_op('='): init=self.parse_expr(); has=True
                props.append((nm,init,has))
                if not self.accept_op(','): break
            self.accept_op(';'); return ('property',line,modifiers,props)
        if self.peek().t=='IDENT':
            # typed property: type $prop ;
            # consume type tokens
            save=self.pos
            type_toks=[]
            if self.is_op('?'): self.next()
            while self.peek().t=='IDENT' or self.is_op('\\') or self.is_op('|') or self.is_op('&'):
                # stop if next is VAR handled
                if self.peek().t=='VAR': break
