        for cond,body in node[2]:
            if to_bool(self.eval(cond,scope)):
                self.exec_stmts(body,scope); return
        if node[3] is not None: self.exec_stmts(node[3],scope)
        return
    if kind=='while':
        while to_bool(self.eval(node[2],scope)):
            try: self.exec_stmts(node[3],scope)
            except BreakExc as b:
