                b.n-=1; raise
            except ContinueExc as c:
                if c.n<=1: continue
                c.n-=1; raise
        return
    if kind=='do':
        while True:
            try: self.exec_stmts(node[2],scope)
            except BreakExc as b:
                if b.n<=1: break
                b.n-=1; raise
            except ContinueExc as c:
                if c.n>1: c.n-=1; raise
            if not to_bool(self.eval(node[3],scope)): break
