            if node[4] is not None: self.exec_stmts(node[4],scope)
        return
    if kind=='return':
        v=None
        if node[2] is not None: v=self.eval(node[2],scope)
        # copy array
        if isinstance(v,PhpArray): v=v.copy()
        raise ReturnExc(v)
    if kind=='break':
        n=1
        if node[2] is not None: n=to_int(self.eval(node[2],scope))
        raise BreakExc(n)
    if kind=='continue':
        n=1
        if node[2] is not None: n=to_int(self.eval(node[2],scope))
        raise ContinueExc(n)
