            # if conditional decl etc just register when executed
            self.functions[fq.lower()]=fd
        return
    if kind=='classdecl':
        self.declare_class(node,scope); return
    if kind=='global':
        for vn in node[2]:
            if vn in self.global_scope.vars: scope.vars[vn]=self.global_scope.vars[vn]
            else:
                c=Cell(None); self.global_scope.vars[vn]=c; scope.vars[vn]=c
        return
    if kind=='staticvar':
        store=scope.static_store if scope.static_store is not None else (self.global_scope.vars)
        # For functions static_store is FuncDef.static_vars dict
        for name,init in node[2]:
            if isinstance(store,dict):
                if name not in store:
                    v=self.eval(init,scope) if init is not None else None
                    store[name]=Cell(v)
                scope.vars[name]=store[name]
            else:
                pass
        return
    if kind=='unset':
        for e in node[2]: self.do_unset(e,scope,line)
        return
    if kind=='constdecl':
        for name,init in node[2]:
