def php_iter_items(interp,v,line=0):
    if isinstance(v,PhpArray): return [(k,c.v) for k,c in list(v.m.items())]
    if isinstance(v,PhpObject):
        # Traversable?
        if interp.find_method(v.cls,'getIterator'):
            it=interp.call_method(v,'getIterator',[],line=line)
            return php_iter_items(interp,it,line)
        if interp.is_subclass(v.cls,'Traversable') or v.cls in ('ArrayObject','ArrayIterator'):
            return interp.iterate_object(v,line)
        # foreach over object properties visible
        return [(k,c.v) for k,c in v.props.items()]
    if v is None:
        interp.warning("foreach() argument must be of type array|object, null given",line); return []
    if isinstance(v,bool) or isinstance(v,(int,float,str)):
        tn=gettype_name(v)
        interp.warning(f"foreach() argument must be of type array|object, {tn} given",line); return []
    return []
