def _resolve_class_name(self,name,scope=None):
    if not isinstance(name,str): return name
    if name.startswith('\\'): return name.lstrip('\\')
    low=name.lower()
    if low in ('self','parent','static'): return name
    # aliased use?
    # scope ns
    ns=(scope.ns if scope else self.current_ns) or ""
    # first segment alias check via current_uses (only for global code) ignore
    if ns:
        candidate=ns+'\\'+name
        if _find_class(self,candidate): return candidate
        # also if no class, PHP still resolves to ns\name for new (error will show fq)
        # But for names that are builtin global, if candidate not exists return global if exists
        if _find_class(self,name): return name
        return candidate
    return name
