def _assign_target(self,target,v,scope,line=0):
    # target: vartarget/listtarget or expr node
    if isinstance(target,tuple) and target[0]=='vartarget':
        expr=target[2]
        ref=self.eval_ref(expr,scope,line)
        if ref: ref.set(v); return
        return
    if isinstance(target,tuple) and target[0]=='listtarget':
        items=target[2]
        if isinstance(v,PhpArray):
            # list uses integer keys 0.. but also could be keyed? simplify sequential values
            for idx,it in enumerate(items):
                if it is None: continue
                if idx in v.m: self.assign_target(it,v.m[idx].v,scope,line)
                else:
                    # try by position
                    vals=list(v.m.values())
                    if idx < len(vals): self.assign_target(it,vals[idx].v,scope,line)
                    else: self.assign_target(it,None,scope,line)
        else:
            for it in items:
                if it is not None: self.assign_target(it,None,scope,line)
        return
    # direct expr
    ref=self.eval_ref(target,scope,line)
    if ref: ref.set(v)
