def _eval(self,node,scope):
    if node is None: return None
    kind=node[0]; line=node[1] if len(node)>1 and isinstance(node[1],int) else self.current_line
    prev_line=self.current_line; self.current_line=line
    try:
        return self._eval_inner(node,scope,line)
    finally:
        pass
