def _eval_inner(self,node,scope,line):
    kind=node[0]
    if kind=='lit': return node[2]
    if kind=='dstring': return parse_dstring_parts(self,node[2],scope,line)
    if kind=='var':
        name=node[2]
        if name=='this':
            if scope.this is None:
                self.fatal_error("Using $this when not in object context",line)
            return scope.this
        if name=='GLOBALS':
            a=PhpArray()
            for k,c in self.global_scope.vars.items(): a.m[k]=c
            return a
        cell=scope.get_cell(name,quiet=self.quiet>0,line=line)
        if cell is None:
            # Undefined warning already in get_cell when not quiet
            return None
        return cell.v
    if kind=='magic':
        kw=node[2]
        if kw=='__line__': return line
        if kw=='__file__': return self.current_file
        if kw=='__dir__': return os.path.dirname(os.path.abspath(self.current_file)) if self.current_file not in ("Command line code","Standard input code") else os.getcwd()
        if kw=='__function__': return scope.func or ""
        if kw=='__class__': return scope.cls or ""
        if kw=='__method__': return (scope.cls+"::"+scope.func) if scope.cls and scope.func else (scope.func or "")
        if kw=='__namespace__': return scope.ns or self.current_ns or ""
        if kw=='__trait__': return ""
        return ""
    if kind=='name':
        nm=node[2]
        # constant?
        # true/false/null handled primary
        # class constant via :: handled elsewhere, bare name is constant
        # check namespaced
        candidates=[]
        if nm.startswith('\\'): candidates=[nm.lstrip('\\')]
        else:
            if scope.ns or self.current_ns:
                candidates=[(scope.ns or self.current_ns)+'\\'+nm, nm]
            else: candidates=[nm]
        for cand in candidates:
            if cand in self.constants: return self.constants[cand]
            if cand.lower() in ('true',): return True
            if cand.lower() in ('false',): return False
            if cand.lower() in ('null',): return None
        # INF NAN etc
        if nm=='INF': return math.inf
        if nm=='NAN': return math.nan
        # Could be class name for ::class etc already handled; bare name unknown constant -> Error
        # If it's a class name used as ??? throw
        if not self.quiet:
            # PHP8 throws Error Undefined constant
            obj=self.make_throwable('Error',f'Undefined constant "{nm}"',0,line)
