def php_incdec(v,delta,interp,line):
    if v is None: return 1 if delta>0 else None
    if isinstance(v,bool): return v
    if isinstance(v,(int,float)): return v+delta
    if isinstance(v,str):
        if is_num_str(v): return num_str_parse(v.strip())+delta
        if delta>0: return php_str_increment(v)
        else: return php_str_decrement(v)
    return v
def php_str_increment(s):
    if s=="": return "1"
    lst=list(s); i=len(lst)-1; carry=True
    while i>=0 and carry:
        c=lst[i]
        if '0'<=c<'9': lst[i]=chr(ord(c)+1); carry=False
        elif c=='9': lst[i]='0'
        elif 'a'<=c<'z': lst[i]=chr(ord(c)+1); carry=False
        elif c=='z': lst[i]='a'
        elif 'A'<=c<'Z': lst[i]=chr(ord(c)+1); carry=False
        elif c=='Z': lst[i]='A'
        else: carry=False
        i-=1
    if carry:
        first=s[0]
        if first.isdigit(): lst.insert(0,'1')
        elif 'a'<=first<='z': lst.insert(0,'a')
        elif 'A'<=first<='Z': lst.insert(0,'A')
        else: lst.insert(0,'1')
    return ''.join(lst)
def php_str_decrement(s):
    # simplistic: PHP decrement only numeric? alphanumeric decrement similar borrow
    if s=="": return ""
    lst=list(s); i=len(lst)-1; borrow=True
    while i>=0 and borrow:
        c=lst[i]
        if '1'<=c<='9' or 'b'<=c<='z' or 'B'<=c<='Z': lst[i]=chr(ord(c)-1); borrow=False
        elif c=='0': lst[i]='9'
        elif c=='a': lst[i]='z'
        elif c=='A': lst[i]='Z'
        else: borrow=False
        i-=1
    return ''.join(lst)

def arr_from_props(obj):
    a=PhpArray()
    for k,c in obj.props.items(): a.set(k,c.v)
