def parse_dstring_parts(interp,raw,scope,line):
    # returns string evaluating interpolations in raw (unescaped content as in token)
    out=[]; i=0; n=len(raw)
    while i<n:
        c=raw[i]
        if c=='\\' and i+1<n:
            nxt=raw[i+1]
            mp={'n':'\n','t':'\t','r':'\r','v':'\v','e':'\x1b','f':'\f','\\':'\\','"':'"','$':'$'}
            if nxt in mp: out.append(mp[nxt]); i+=2; continue
            if nxt=='x':
                m=re.match(r'x([0-9a-fA-F]{1,2})',raw[i+1:])
                if m: out.append(chr(int(m.group(1),16))); i+=1+len(m.group(0)); continue
            if nxt=='u':
                m=re.match(r'u\{([0-9a-fA-F]+)\}',raw[i+1:])
                if m: out.append(chr(int(m.group(1),16))); i+=1+len(m.group(0)); continue
            if nxt.isdigit():
                m=re.match(r'([0-7]{1,3})',raw[i+1:])
                if m: out.append(chr(int(m.group(1),8)&0xff)); i+=1+len(m.group(0)); continue
            out.append('\\'+nxt); i+=2; continue
        if c=='{' and i+1<n and raw[i+1]=='$':
            # {$expr}
            depth=1; j=i+1
            while j<n and depth>0:
                if raw[j]=='{': depth+=1
                elif raw[j]=='}': depth-=1
                j+=1
            expr_src=raw[i+1:j-1]
            try:
                toks=lex_file("<?php "+expr_src, interp.current_file)
                p=Parser(toks,interp.current_file); p.pos=1 # skip OPEN? toks[0] OPEN
                # lex_file: first token OPEN, then expr
                e=p.parse_expr()
                v=interp.eval(e,scope)
                out.append(to_string(v,interp,line))
            except Exception as ex:
                if isinstance(ex,ThrowExc): raise
            i=j; continue
        if c=='$':
            # ${var} deprecated
            if i+1<n and raw[i+1]=='{':
                depth=1; j=i+2
                while j<n and depth>0:
                    if raw[j]=='{': depth+=1
                    elif raw[j]=='}': depth-=1
                    j+=1
                name=raw[i+2:j-1]
                interp.deprecated("Using ${var} in strings is deprecated, use {$var} instead",line)
                # name may be expr
                cell=scope.get_cell(name,quiet=True,line=line) if re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*',name) else None
                if cell: out.append(to_string(cell.v,interp,line))
                else:
                    try:
                        toks=lex_file("<?php $"+name, interp.current_file); p=Parser(toks,interp.current_file); e=p.parse_expr(); out.append(to_string(interp.eval(e,scope),interp,line))
                    except: pass
                i=j; continue
            m=re.match(r'\$([A-Za-z_][A-Za-z0-9_]*)',raw[i:])
            if m:
                name=m.group(1); i+=len(m.group(0))
                # array index [..] or ->prop
                suffix_val=None; has_suffix=False
                if i<n and raw[i]=='[':
                    j=raw.find(']',i)
                    if j!=-1:
                        idx_src=raw[i+1:j]
                        # evaluate idx: number, string bare, $var
                        if idx_src.startswith('$'):
                            cell=scope.get_cell(idx_src[1:],quiet=True)
                            idx=cell.v if cell else None
                        elif idx_src.isdigit() or (idx_src[0]=='-' and idx_src[1:].isdigit()): idx=int(idx_src)
                        elif idx_src.startswith("'") : idx=idx_src[1:-1]
                        else: idx=idx_src
                        cell=scope.get_cell(name,quiet=True)
                        base=cell.v if cell else None
                        if isinstance(base,PhpArray): suffix_val=base.get(idx,interp,line,quiet=interp.quiet>0) if idx is not None else None
                        elif isinstance(base,str) and isinstance(idx,int): suffix_val=base[idx] if 0<=idx<len(base) else ""
                        has_suffix=True; i=j+1
                elif raw.startswith('->',i):
                    m2=re.match(r'->([A-Za-z_][A-Za-z0-9_]*)',raw[i:])
                    if m2:
                        cell=scope.get_cell(name,quiet=True); base=cell.v if cell else None
                        if isinstance(base,PhpObject): suffix_val=interp.get_prop(base,m2.group(1),line,scope)
                        has_suffix=True; i+=len(m2.group(0))
                if has_suffix:
                    out.append(to_string(suffix_val,interp,line))
                else:
                    cell=scope.get_cell(name,quiet=False,line=line) if not interp.quiet else scope.get_cell(name,quiet=True)
                    # get_cell already warned? It warns via interp.warning if not quiet? Our Scope.get_cell warns when not quiet.
                    v=cell.v if cell else None
                    out.append(to_string(v,interp,line))
                continue
            out.append('$'); i+=1; continue
        out.append(c); i+=1
    return ''.join(out)

def _eval(self,node,scope):
    if node is None: return None
