                    try: default=self.eval(pinit,scope)
                    except: default=None
                if is_static:
                    cd.static_props[pname]=Cell(default.copy() if isinstance(default,PhpArray) else default)
                else:
                    cd.prop_dict[pname]={'default':default,'vis':vis,'modifiers':m[2]}
