@B('round')
def bf_round(interp,args,line,scope):
    n=to_float(aval(args,0)); prec=aint(interp,args,1,line) if len(args)>1 else 0; mode=aint(interp,args,2,line,1) if len(args)>2 else 1
    factor=10**prec
    x=n*factor
    # PHP rounding half away from zero default (mode 1)
    if mode==2: # half towards zero
        r=math.floor(x) if x>=0 and x%1>0.5 else math.ceil(x) if x<0 and abs(x)%1>0.5 else (math.floor(x) if x>=0 else math.ceil(x))
        # simplified use python round for even etc below
    if mode==3: # half even
        r=round(x)
    elif mode==4: # half odd
        r=round(x)
        if r%2==0: r+=1 if x>=r else -1 if False else r
        # approximate
    else:
        r=math.floor(x+0.5) if x>=0 else math.ceil(x-0.5)
    return float(r/factor)
