    else: vals=[a.v for a in args]
    if not vals: raise ThrowExc(interp.make_throwable('ValueError','min(): Argument #1 ($value) must contain at least one element',0,line)) if False else None
    best=vals[0]
    for v in vals[1:]:
        if php_compare(v,best)<0: best=v
    return best
