def php_sprintf(interp,fmt,args_vals,line):
    out=""; i=0; arg_idx=0
    while i < len(fmt):
        if fmt[i]!='%':
            out+=fmt[i]; i+=1; continue
        if i+1 < len(fmt) and fmt[i+1]=='%': out+='%'; i+=2; continue
        start=i; i+=1
