        if prec is not None: s=s.rjust(prec,'0')
        sign='-' if n<0 else ('+' if sign_force else (' ' if ' ' in flags else ''))
        core=sign+s
    elif conv=='u':
        n=to_int(val,interp,line) & 0xffffffffffffffff; core=str(n)
    elif conv in 'eEfgG':
        n=to_float(val)
        p=prec if prec is not None else 6
        try: core=f"{n:.{p}{conv}}"
        except: core=str(n)
        if conv=='g' or conv=='G':
            # python similar
            pass
        if sign_force and not core.startswith('-'): core='+'+core
    elif conv in 'xX':
        n=to_int(val,interp,line)
        core=format(n & 0xffffffffffffffff, 'x' if conv=='x' else 'X') if n<0 else format(n,'x' if conv=='x' else 'X')
        if alt: core='0'+conv.lower()+core if False else ('0x' if conv=='x' else '0X')+core
    elif conv=='o':
        n=to_int(val,interp,line); core=format(n,'o'); 
        if alt: core='0'+core
    elif conv=='b':
        n=to_int(val,interp,line); core=format(n,'b')
    elif conv=='c':
        n=to_int(val,interp,line); core=chr(n & 0xff)
    elif conv=='s':
