def dispatch_generator(interp,obj,m,vals,line):
    gen=obj.extra.get('gen')
    if m=='current':
        if gen is None: return None
        if not gen.started: gen.resume()
        return gen.current
    if m=='key':
        if gen is None: return None
        if not gen.started: gen.resume()
        return gen.current_key if gen.current_key is not None else 0
    if m=='valid': return gen is not None and not gen.closed
    if m=='next': 
        if gen: gen.resume(None)
        return None
    if m=='send':
        if gen: return gen.resume(vals[0] if vals else None)
        return None
    if m=='throw':
        if gen: return gen.resume(throw_obj=vals[0] if vals else None)
        return None
    if m=='rewind':
        if gen and gen.started and not gen.closed: raise ThrowExc(interp.make_throwable('Exception','Cannot rewind a generator that was already run',0,line))
        if gen: gen.resume()
        return None
    if m=='getreturn': return gen.getReturn() if gen else None
    if m=='__wakeup': raise ThrowExc(interp.make_throwable('Exception','Unserialization of Generator is not allowed',0,line))
    raise KeyError(m)

