@B('pack')
def bf_pack(interp,args,line,scope):
    fmt=astr(interp,args,0,line); vals=[a.v for a in args[1:]]
    # only c,C,s,S,i,I,l,L,f,d etc naive struct
    out=b""
    vi=0
    endian='<'
    for ch in fmt:
        if ch=='x': out+=b'\x00'; continue
        if vi>=len(vals): break
        v=vals[vi]; vi+=1
        if ch in 'cC': out+=struct.pack('b' if ch=='c' else 'B', int(v)&0xff if ch=='C' else (int(v) if int(v)<128 else int(v)-256))
        elif ch in 'sS': out+=struct.pack(endian+('h' if ch=='s' else 'H'), int(v))
        elif ch in 'iI': out+=struct.pack(endian+('i' if ch=='i' else 'I'), int(v))
        elif ch in 'lL': out+=struct.pack(endian+('l' if ch=='l' else 'L'), int(v))
        elif ch in 'qQ': out+=struct.pack(endian+('q' if ch=='q' else 'Q'), int(v))
        elif ch=='f': out+=struct.pack('f', float(v))
        elif ch=='d': out+=struct.pack('d', float(v))
        elif ch=='a' or ch=='A': out+=str(v).encode()
    return out.decode('latin1')
