def bf_unpack(interp,args,line,scope):
    fmt=astr(interp,args,0,line); data=astr(interp,args,1,line).encode('latin1'); a=PhpArray()
    size_map={'c':1,'C':1,'s':2,'S':2,'i':4,'I':4,'l':4,'L':4,'f':4,'d':8}
    off=aint(interp,args,2,line) if len(args)>2 else 0
    i=0; pos=off
    # format like "C1/a..."
    parts=fmt.split('/')
    for part in parts:
        if not part: continue
        m=re.match(r'([a-zA-Z])(\d*|\*)(.*)',part)
        if not m: continue
        code,count,name=m.group(1),m.group(2),m.group(3)
        cnt=int(count) if count.isdigit() else 1
        for j in range(cnt):
            key=name if cnt==1 and name else (f"{name}{j+1}" if name else j+1)
            if code in 'aA':
                ln=cnt if count else 1; val=data[pos:pos+ln].decode('latin1'); a.set(key,val); pos+=ln; break
            sz=size_map.get(code,1); chunk=data[pos:pos+sz]; pos+=sz
            fmtc={'c':'b','C':'B','s':'h','S':'H','i':'i','I':'I','l':'l','L':'L','f':'f','d':'d'}.get(code,'B')
            try: val=struct.unpack('<'+fmtc,chunk)[0]
