def ini_diff_text(interp):
    lines=[('html_errors','1','0'),('implicit_flush','0','1'),('max_execution_time','30','0')]
    # Build diff based on built-in default vs cli modified defaults plus user overrides
    diffs={'html_errors':('1','0'),'implicit_flush':('0','1'),'max_execution_time':('30','0')}
    # default ini php built-in (not CLI): memory_limit etc 128M same so user overrides
    builtin_defaults={'memory_limit':'128M'}
    for k,v in interp.ini_overrides.items():
        if k in diffs: continue
        default=builtin_defaults.get(k)
        if default is None:
            # get from DEFAULT_INI display raw?
            if k in DEFAULT_INI: default=DEFAULT_INI[k][1]
            else: continue
        if str(default)!=str(v): diffs[k]=(str(default),str(v))
