        pattern=r'\n'+re.escape(name)+r'\n(.*?)(?=\n(?:[A-Za-z][^\n]*\n\n|Additional Modules)|\Z)'
        m=re.search(pattern, "\n"+PHPINFO_BASE, re.S)
        if m:
            sys.stdout.write(f"\n{name}\n\n{m.group(1).strip()}\n" if False else f"\n{name}\n\n")
            # Simplify: extract from base by splitting
            lines=PHPINFO_BASE.splitlines()
            try:
                idx=[i for i,l in enumerate(lines) if l.strip()==name][0]
            except: idx=-1
            if idx>=0:
                j=idx+1
                while j < len(lines):
                    # next section header is known module names
                    if lines[j] in MODULES+['Zend OPcache','Additional Modules'] and j>idx+1: break
                    j+=1
                section="\n".join(lines[idx+1:j]).strip("\n")
                # php --ri formats like Core: starts with PHP Version => etc included in section already
                sys.stdout.write(section+"\n"); return 0
    sys.stdout.write(f"\n{name}\n\nPHP Version => 8.6.0-dev\n"); return 0

