def format_stack_trace(interp,obj=None):
    lines=[]
    # call_stack has frames for functions in progress; top current is last?
    frames=list(reversed(interp.call_stack))
    for i,fr in enumerate(frames):
        file=fr.get('file',''); line=fr.get('line',0); fn=fr.get('function','')
        args_str=""
        if fr.get('args'):
            parts=[]
            for a in fr['args']:
                v=a.v if isinstance(a,Arg) else a
                parts.append(trace_arg_str(interp,v))
            args_str=", ".join(parts)
        loc=f"{file}({line}): " if file else ""
        if fr.get('class'): loc+=f"{fr['class']}{fr.get('type','->')}{fn}({args_str})"
        else: loc+=f"{fn}({args_str})"
        lines.append(f"#{i} {loc}")
