        return f"'{s}'"
    if v is None: return "null"
    if isinstance(v,bool): return "true" if v else "false"
    if isinstance(v,(int,float)): return float_dump(v) if isinstance(v,float) else str(v)
    if isinstance(v,PhpArray): return "Array"
    if isinstance(v,PhpObject): return f"Object({v.cls})"
