    if isinstance(obj,PhpObject):
        msg=obj.props['message'].v if 'message' in obj.props else obj.extra.get('msg','')
        file=obj.props['file'].v if 'file' in obj.props and obj.props['file'].v else interp.current_file
        ln=obj.props['line'].v if 'line' in obj.props and obj.props['line'].v else (line_override or interp.current_line)
