def run_shutdown(interp):
    if getattr(interp,'in_shutdown',False): return
    interp.in_shutdown=True
    for cb,vals in list(interp.shutdown_funcs):
        try: interp.call_callable(cb,vals,0)
        except: pass
    # flush output buffers
    while interp.output_buffers:
        buf,cb=interp.output_buffers.pop()
        data=''.join(buf)
        if cb:
            try: data=to_string(interp.call_callable(cb,[data],0),interp,0)
            except: pass
        # write to stdout directly (avoid recursion)
        try: sys.stdout.write(data)
        except: pass

