                ext=os.path.splitext(target)[1]
                content_type={'.html':'text/html; charset=UTF-8','.txt':'text/plain; charset=UTF-8','.css':'text/css; charset=UTF-8','.js':'text/javascript; charset=UTF-8','.png':'image/png','.jpg':'image/jpeg','.gif':'image/gif','.svg':'image/svg+xml'}.get(ext,'application/octet-stream')
