# Type coercion / validation (appended, used by bind/return)
def type_str_from_tokens(tokens):
    if not tokens: return ""
    s=""; 
    for tok in tokens:
        if tok=='|': s+='|'
        elif tok=='&': s+='&'
        elif tok=='?': s+='?'
        elif tok=='\\': s+='\\'
        else: s+=tok
    return s
def coerce_type_value(interp,v,typestr,line,scope=None):
    # returns (ok,coerced)
    if not typestr or typestr.lower()=='mixed': return True,v
    ts=typestr.strip()
    if '&' in ts:
        parts=ts.split('&')
        cur=v
        for part in parts:
            ok,nv=coerce_single_type(interp,cur,part,line,scope)
            if not ok: return False,v
            cur=nv
        return True,cur
    if '|' in ts:
        # null / false special included
        for part in ts.split('|'):
            ok,nv=coerce_single_type(interp,v,part,line,scope)
            if ok: return True,nv
        return False,v
    return coerce_single_type(interp,v,ts,line,scope)
def coerce_single_type(interp,v,ts,line,scope):
    nullable=False
    if ts.startswith('?'): nullable=True; ts=ts[1:]
    low=ts.lower()
    if v is None:
        return (True,None) if nullable or low in ('null','mixed') else (False,v)
    if low=='mixed': return True,v
    if low=='int' or low=='integer':
        if isinstance(v,bool): return True,1 if v else 0
        if isinstance(v,int): return True,v
        if isinstance(v,float):
            if math.isnan(v) or math.isinf(v): return False,v
            if v!=int(v): interp.deprecated(f"Implicit conversion from float {float_dump(v)} to int loses precision",line)
            return True,int(v)
        if isinstance(v,str) and is_num_str(v):
            n=num_str_parse(v.strip())
            if isinstance(n,float):
                if n!=int(n): interp.deprecated(f"Implicit conversion from float {float_dump(n)} to int loses precision",line)
